// TestUpdateValidationHTTP sends requests the API refuses before any job is
// queued.
func (s *APIPublicTestSuite) TestUpdateValidationHTTP() {
	s.api.Run(s.T(), []servertest.Case{
		{
			Name: "when the target is not an agent, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node/nowhere/interface/osapi0",
				Body:   `{"name":"osapi0","type":"dummy","dhcp4":true}`,
			},
			Token:    servertest.Write,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when the target is empty, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node//interface/osapi0",
				Body:   `{"name":"osapi0","type":"dummy","dhcp4":true}`,
			},
			Token:    servertest.Write,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when the body is not JSON, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{`,
			},
			Token:    servertest.Write,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when type has the wrong type, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"type":[]}`,
			},
			Token:    servertest.Write,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when sent an address without a prefix, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0","addresses":["10.0.1.5"]}`,
			},
			Token:    servertest.Write,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when sent more than 16 addresses, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0","addresses":["10.0.1.5/24","10.0.1.5/24","10.0.1.5/24","10.0.1.5/24","10.0.1.5/24","10.0.1.5/24","10.0.1.5/24","10.0.1.5/24","10.0.1.5/24","10.0.1.5/24","10.0.1.5/24","10.0.1.5/24","10.0.1.5/24","10.0.1.5/24","10.0.1.5/24","10.0.1.5/24","10.0.1.5/24"]}`,
			},
			Token:    servertest.Write,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when sent an IPv4 gateway that is not IPv4, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0","gateway4":"fe80::1"}`,
			},
			Token:    servertest.Write,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when sent an IPv6 gateway that is not IPv6, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0","gateway6":"10.0.1.1"}`,
			},
			Token:    servertest.Write,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when sent an MTU below 68, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0","mtu":10}`,
			},
			Token:    servertest.Write,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when sent an MTU above 9000, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0","mtu":9001}`,
			},
			Token:    servertest.Write,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when sent a MAC address netplan does not take, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0","mac_address":"0000.5e00.5301"}`,
			},
			Token:    servertest.Write,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when sent a name that is not an interface name, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node/server1/interface/eth0%3Breboot",
				Body:   `{"name":"eth0;reboot"}`,
			},
			Token:    servertest.Write,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when sent a type osapi does not know, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0","type":"vlan"}`,
			},
			Token:    servertest.Write,
			WantCode: http.StatusBadRequest,
		},
	})
}

// TestUpdateRBACHTTP sends tokens that do not grant interface:write.
func (s *APIPublicTestSuite) TestUpdateRBACHTTP() {
	s.api.Run(s.T(), []servertest.Case{
		{
			Name: "when there is no token, it is a 401",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0","type":"dummy","dhcp4":true}`,
			},
			Token:    servertest.NoToken,
			WantCode: http.StatusUnauthorized,
		},
		{
			Name: "when the token lacks interface:write, it is a 403",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0","type":"dummy","dhcp4":true}`,
			},
			Token:    servertest.Lacking,
			WantCode: http.StatusForbidden,
		},
		{
			Name: "when the token has only the read role, it is a 403",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0","type":"dummy","dhcp4":true}`,
			},
			Token:    servertest.Read,
			WantCode: http.StatusForbidden,
		},
		{
			Name: "when the token has the admin role, the request runs",
			Request: servertest.Request{
				Method: http.MethodPut,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0","type":"dummy","dhcp4":true}`,
			},
			Token: servertest.Admin,
			Job: servertest.Modify(
				"server1",
				"interface.update",
				iface.UpdateInput{
					DHCP4: true,
					Name:  "osapi0",
					Type:  types.InterfaceType("dummy"),
				},
				servertest.Skipped("server1"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"unsupported","hostname":"server1","status":"skipped"}]}`,
		},
	})
}

// TestDelete sends DELETE /api/node/{hostname}/interface/{name} and checks
// each answer's response.
func (s *APIPublicTestSuite) TestDelete() {
	s.api.Run(s.T(), []servertest.Case{
		{
			Name: "when the example \"A dummy interface osapi configures\" is sent, the host's result is returned",
			Request: servertest.Request{
				Method: http.MethodDelete,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0"}`,
			},
			Token: servertest.Write,
			Job: servertest.Modify(
				"server1",
				"interface.delete",
				iface.DeleteInput{Name: "osapi0"},
				servertest.Completed("server1", `{"name":"osapi0","changed":true}`),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"changed":true,"hostname":"server1","name":"osapi0","status":"ok"}]}`,
		},
		{
			Name: "when the example \"A dummy interface osapi configures\" is broadcast, every host's result is returned",
			Request: servertest.Request{
				Method: http.MethodDelete,
				Path:   "/api/node/_all/interface/osapi0",
				Body:   `{"name":"osapi0"}`,
			},
			Token: servertest.Write,
			Job: servertest.Modify(
				"_all",
				"interface.delete",
				iface.DeleteInput{Name: "osapi0"},
				servertest.Completed("server1", `{"name":"osapi0","changed":true}`),
				servertest.Skipped("server2"),
				servertest.Failed("server3", "boom"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"changed":true,"hostname":"server1","name":"osapi0","status":"ok"},{"error":"unsupported","hostname":"server2","status":"skipped"},{"error":"boom","hostname":"server3","status":"failed"}]}`,
		},
		{
			Name: "when the example \"An interface osapi does not configure\" is sent, the host's result is returned",
			Request: servertest.Request{
				Method: http.MethodDelete,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0"}`,
			},
			Token: servertest.Write,
			Job: servertest.Modify(
				"server1",
				"interface.delete",
				iface.DeleteInput{Name: "osapi0"},
				servertest.Completed("server1", `{"name":"osapi0","changed":false}`),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"changed":false,"hostname":"server1","name":"osapi0","status":"ok"}]}`,
		},
		{
			Name: "when the example \"An interface osapi does not configure\" is broadcast, every host's result is returned",
			Request: servertest.Request{
				Method: http.MethodDelete,
				Path:   "/api/node/_all/interface/osapi0",
				Body:   `{"name":"osapi0"}`,
			},
			Token: servertest.Write,
			Job: servertest.Modify(
				"_all",
				"interface.delete",
				iface.DeleteInput{Name: "osapi0"},
				servertest.Completed("server1", `{"name":"osapi0","changed":false}`),
				servertest.Skipped("server2"),
				servertest.Failed("server3", "boom"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"changed":false,"hostname":"server1","name":"osapi0","status":"ok"},{"error":"unsupported","hostname":"server2","status":"skipped"},{"error":"boom","hostname":"server3","status":"failed"}]}`,
		},
		{
			Name: "when the host skips it, its row says skipped",
			Request: servertest.Request{
				Method: http.MethodDelete,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0"}`,
			},
			Token: servertest.Write,
			Job: servertest.Modify(
				"server1",
				"interface.delete",
				iface.DeleteInput{Name: "osapi0"},
				servertest.Skipped("server1"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"unsupported","hostname":"server1","status":"skipped"}]}`,
		},
		{
			Name: "when the host fails it, its row says failed",
			Request: servertest.Request{
				Method: http.MethodDelete,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0"}`,
			},
			Token: servertest.Write,
			Job: servertest.Modify(
				"server1",
				"interface.delete",
				iface.DeleteInput{Name: "osapi0"},
				servertest.Failed("server1", "boom"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"boom","hostname":"server1","status":"failed"}]}`,
		},
		{
			Name: "when the host never answers, its row says timeout",
			Request: servertest.Request{
				Method: http.MethodDelete,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0"}`,
			},
			Token: servertest.Write,
			Job: servertest.Modify(
				"server1",
				"interface.delete",
				iface.DeleteInput{Name: "osapi0"},
				servertest.TimedOut("server1"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"","hostname":"server1","status":"timeout"}]}`,
		},
		{
			Name: "when the job client fails, it is a 500",
			Request: servertest.Request{
				Method: http.MethodDelete,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0"}`,
			},
			Token: servertest.Write,
			Job: servertest.Modify(
				"server1",
				"interface.delete",
				iface.DeleteInput{Name: "osapi0"},
			).Fails(servertest.ErrUnreachable),
			WantCode: http.StatusInternalServerError,
		},
		{
			Name: "when broadcast and the job client fails, it is a 500",
			Request: servertest.Request{
				Method: http.MethodDelete,
				Path:   "/api/node/_all/interface/osapi0",
				Body:   `{"name":"osapi0"}`,
			},
			Token: servertest.Write,
			Job: servertest.Modify(
				"_all",
				"interface.delete",
				iface.DeleteInput{Name: "osapi0"},
			).Fails(servertest.ErrUnreachable),
			WantCode: http.StatusInternalServerError,
		},
		{
			Name: "when the host does not have it, it is a 404",
			Request: servertest.Request{
				Method: http.MethodDelete,
				Path:   "/api/node/server1/interface/osapi0",
				Body:   `{"name":"osapi0"}`,
			},
			Token: servertest.Write,
			Job: servertest.Modify(
				"server1",
				"interface.delete",
				iface.DeleteInput{Name: "osapi0"},
			).Fails(servertest.NotFound("server1")),
			WantCode: http.StatusNotFound,
		},
	})
}

